  "claims": [
    {
      "claim": "Diphemanil methylsulphate, a quaternary ammonium antimuscarinic, showed very low oral bioavailability in healthy subjects after a 250 mg oral dose, providing direct class-level evidence that permanent-cation antimuscarinics can have F well below 20%.",
      "card_ids": ["C06"]
    },
    {
      "claim": "DX-9065a, a small molecule with strong basic amidino groups, had human oral bioavailability of only 2–3% in clinical trials (C01), 2.8 ± 1.5% as a conventional gelatin capsule (C04), and 3% as a fasted conventional capsule (C16), showing that strong cationic character is associated with F < 20%.",
      "card_ids": ["C01", "C04", "C16"]
    },
    {
      "claim": "L2 DX-9065a records consistently show low F across species (rat 4.6 ± 1.2%, baboon 5–12%, fasted rat 10.8 ± 2.0%) and attribute the low human F to electrostatic/bile-acid interactions, reinforcing the low-F class evidence.",
      "card_ids": ["C35", "C44", "C45", "C34"]
    },
    {
      "claim": "Propafenone under rifampin shows F = 4 ± 3% in elderly CYP2D6 extensive metabolizers (C14, C49), but L2 also shows F = 48 ± 8% in poor metabolizers (C40) and baseline F = 30 ± 24% in elderly EMs (C43); this context is metabolism- and phenotype-dependent and is not a clean transferable low-F outcome for the quaternary ammonium query.",
      "card_ids": ["C14", "C49", "C40", "C43"]
    },
    {
      "claim": "Phenylephrine L2 records report absolute F ~37.5–38% (C41, C53), above the 20% threshold, but phenylephrine is a non-quaternary phenolamine whose low oral efficacy is due to presystemic conjugation; it does not provide affirmative evidence for the query.",
      "card_ids": ["C41", "C53"]
    },
    {
      "claim": "Levodropropizine L2 records report high relative bioavailability (C26, C31, C46), but the molecule lacks a quaternary ammonium and is structurally unrelated to the query; this does not support F >= 20% for the query.",
      "card_ids": ["C26", "C31", "C46"]
    }
  ],
  "new_evidence_assessment": [
    {
